const bundle = {
  gaps: { reaudit: '7/7 owned' },
  budgets: { p99margin: 25, costMargin: 30 },
  safety: { chaosPass: true, attackGold: '12/12' },
  ops: { dashboards: 3, alertsTested: true },
  residual: [{ risk: 'novel attacks', owner: 'security', date: '2027-01-15' }],
};
const checks = [
  ['gaps closed', bundle.gaps.reaudit === '7/7 owned'],
  ['headroom positive', bundle.budgets.p99margin > 0 && bundle.budgets.costMargin > 0],
  ['chaos proven', bundle.safety.chaosPass === true],
  ['attack gold full', bundle.safety.attackGold === '12/12'],
  ['residuals owned', bundle.residual.every((r) => r.owner && r.date)],
];
for (const [label, ok] of checks) console.log((ok ? 'PASS ' : 'FAIL ') + label);
console.log(checks.every(([, ok]) => ok) ? 'launch approved (conditional)' : 'launch BLOCKED');

